'use client';

import React from 'react';

/** Props for the {@link Toggle} component. */
export interface ToggleProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type'> {
  /** Whether the toggle is on (controlled). */
  checked?: boolean;
  /** Default checked state (uncontrolled). */
  defaultChecked?: boolean;
  /** Called when the toggle value changes. */
  onCheckedChange?: (checked: boolean) => void;
  /** Label text displayed next to the toggle. */
  label?: string;
  /** Additional CSS class names on the outer wrapper. */
  className?: string;
}

/**
 * Two-state switch with dither texture on the active thumb.
 * Renders a `<label>` wrapping a hidden checkbox and a styled thumb.
 */
export const Toggle = React.forwardRef<HTMLInputElement, ToggleProps>(
  ({ checked, defaultChecked, onCheckedChange, label, className, onChange, ...rest }, ref) => {
    const handleChange = React.useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        onCheckedChange?.(e.target.checked);
        onChange?.(e);
      },
      [onCheckedChange, onChange],
    );

    return (
      <label className={`sk-toggle${className ? ` ${className}` : ''}`}>
        <input
          ref={ref}
          type="checkbox"
          className="sk-toggle__input"
          checked={checked}
          defaultChecked={defaultChecked}
          onChange={handleChange}
          {...rest}
        />
        <span className="sk-toggle__thumb" />
        {label && <span className="sk-toggle__label">{label}</span>}
      </label>
    );
  },
);

Toggle.displayName = 'Toggle';

/**
 * skeehn — Toggle Component
 *
 * @component sk-toggle
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    :checked | :disabled | [data-loading] | [data-skeleton]
 * @slots     __input | __thumb | __label
 * @a11y      Hidden input for screen readers, label association, focus-visible
 * @print     Shows checked/unchecked text state
 */

.sk-toggle { display: inline-flex; align-items: center; gap: var(--sk-space-2); cursor: pointer; user-select: none; font-family: var(--sk-font-mono); }
.sk-toggle__input { position: absolute; opacity: 0; width: 0; height: 0; }
.sk-toggle__thumb { width: 2.5rem; height: 1.25rem; background: hsl(var(--sk-muted)); border: var(--sk-border); border-radius: var(--sk-radius); position: relative; transition: all var(--sk-transition); flex-shrink: 0; }
.sk-toggle__thumb::before { content: ""; position: absolute; top: 2px; left: 2px; width: calc(1.25rem - 4px); height: calc(1.25rem - 4px); background: hsl(var(--sk-background)); border: var(--sk-border); border-radius: var(--sk-radius); transition: all var(--sk-transition); }
.sk-toggle__input:checked + .sk-toggle__thumb { background: hsl(var(--sk-primary)); border-color: hsl(var(--sk-primary)); }
.sk-toggle__input:checked + .sk-toggle__thumb::before { transform: translateX(1.25rem); }
.sk-toggle__input:checked + .sk-toggle__thumb::after { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-b2); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.12) * 0.6); border-radius: inherit; pointer-events: none; }
.sk-toggle__label { font-size: var(--sk-font-size-sm); color: hsl(var(--sk-foreground)); letter-spacing: 0.02em; }

/* Micro-interactions */
.sk-toggle__input:focus-visible + .sk-toggle__thumb { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); box-shadow: 0 0 0 4px hsl(var(--sk-ring) / 0.12); }
.sk-toggle:hover .sk-toggle__thumb { border-color: hsl(var(--sk-foreground) / 0.3); }

/* Pixel variant */
.sk-toggle[data-variant="pixel"] .sk-toggle__thumb { border: 2px solid hsl(var(--sk-foreground)); box-shadow: 2px 2px 0 hsl(var(--sk-foreground)); border-radius: 0; }
.sk-toggle[data-variant="pixel"] .sk-toggle__thumb::before { border-radius: 0; border: 1px solid hsl(var(--sk-foreground)); }

/* Retro variant */
.sk-toggle[data-variant="retro"] .sk-toggle__input:checked + .sk-toggle__thumb { box-shadow: 0 0 6px hsl(var(--sk-primary) / 0.3); }

/* ASCII variant */
.sk-toggle[data-variant="ascii"] .sk-toggle__thumb { background: transparent; border: none; width: 3rem; }
.sk-toggle[data-variant="ascii"] .sk-toggle__thumb::before { background: transparent; border: 1px solid hsl(var(--sk-foreground)); content: "[ ]"; width: auto; height: auto; font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); display: flex; align-items: center; justify-content: center; }
.sk-toggle[data-variant="ascii"] .sk-toggle__input:checked + .sk-toggle__thumb::before { content: "[x]"; }

/* Loading */
.sk-toggle[data-loading] { pointer-events: none; opacity: 0.6; }
.sk-toggle[data-loading] .sk-toggle__thumb { animation: sk-pulse-dither 1.5s ease-in-out infinite; }

/* Skeleton */
.sk-toggle[data-skeleton] .sk-toggle__thumb { background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-card-shimmer 1.8s ease-in-out infinite; }
.sk-toggle[data-skeleton] .sk-toggle__label { color: transparent; background: hsl(var(--sk-muted)); border-radius: var(--sk-radius); }

@media print {
  .sk-toggle { box-shadow: none; }
  .sk-toggle__thumb, .sk-toggle__thumb::before, .sk-toggle__thumb::after { animation: none; }
  .sk-toggle[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-toggle__thumb, .sk-toggle__thumb::before { transition: none; }
  .sk-toggle[data-loading] .sk-toggle__thumb { animation: none; }
  .sk-toggle[data-skeleton] .sk-toggle__thumb { animation: none; background: hsl(var(--sk-muted)); }
}
